\label{prop:2var-rog-ram}
In $\mathcal{T}_{\mathbb{H}^{\textnormal{-}\hspace{-0.03cm}}}\left(qx^2-x\right)$, one has 
\begin{equation}\label{eq:2var-rog-ram}
    (q; q) \left\langle x; q \right\rangle (qx; q)\ =  
    \sum_{m \in \mathbb{Z}, n \ge 0} \frac{q^{\binom{m}{2} + \binom{n+1}{2}}}{(q; q)_n} (-x)^{m+n}
    \ =\ 
    \frac{\vect{qx^2 - x}{0}}{\left\langle q^2; q^5 \right\rangle} - \frac{\vect{qx^2 - x}{1}}{\left\langle q; q^5 \right\rangle},
\end{equation}
where for $k \in \{0, 1\}$, $\vect{qx^2 - x}{k}$ is the unique function in $\mathcal{T}_{\mathbb{H}^{\textnormal{-}\hspace{-0.03cm}}}\left(qx^2-x\right)$ whose Fourier expansion in $z \in {\mathbb{H}}^-$ has coefficient of $x^j$ equal to $\mathbbm{1}_{j = k}$, for $j \in \{0, 1\}$.

\begin{equation}\label{eq:2var-rog-ram}
    (q; q) \left\langle x; q \right\rangle (qx; q)\ =  
    \sum_{m \in \mathbb{Z}, n \ge 0} \frac{q^{\binom{m}{2} + \binom{n+1}{2}}}{(q; q)_n} (-x)^{m+n}
    \ =\ 
    \frac{\vect{qx^2 - x}{0}}{\left\langle q^2; q^5 \right\rangle} - \frac{\vect{qx^2 - x}{1}}{\left\langle q; q^5 \right\rangle},
\end{equation}

