 \label{prop:monomial-spaces}
Let $d$ be any integer, and $D$ be a $\mathbb{Z}$-invariant domain containing an open horizontal strip $S$ of width $> \textnormal{Im}\ \tau$.
\begin{itemize}
\item[(i)] For any $\alpha \in \mathbb{C}^\times$ (which may depend on the fixed $q$), one has
\[
    \dim \mathcal{T}_D\big(\alpha x^d\big) = 
    \begin{cases} 
    d, \qquad &d > 0, \\
    \mathbbm{1}_{\alpha \in \left\{q^n : n \in \mathbb{Z} \right\}}, \qquad &d = 0, \\
    0, \qquad &d < 0.
    \end{cases}
\]
Moreover, for $d \ge 0$, any $F \in \mathcal{T}_{\mathbb{C}}\left(\alpha x^d\right) \setminus \{0\}$ has exactly $d$ zeros (counting multiplicities) in every fundamental region $\{w - t - u\tau : t, u \in [0, 1) \}$, for $w \in \mathbb{C}$. 
\item[(ii)] For $c \in \mathbb{Z}$ and $s, t \in \{\pm 1\}$,
\begin{equation} \label{eq:dimension}
    \dim \left( \mathcal{T}_{\mathbb{C}} \big(sq^c x^d \big) \cap \mathcal{S}_{\mathbb{C}} \big(tx^{d-2c}\big) \right) = 
    \max\left( 1 + \left\lfloor \frac{d}{2} \right\rfloor 
    -
    \mathbbm{1}_{2 \mid d} \mathbbm{1}_{t = -1}
    -
    \mathbbm{1}_{st = -1} ,\ 0\right).
\end{equation}
So for $d \in \{1, 2\}$, one obtains $\mathcal{T}_{\mathbb{C}}\left(s q^cx\right) \subset \mathcal{S}_{\mathbb{C}}\left(s x^{1-2c}\right)$ and $\mathcal{T}_{\mathbb{C}}\left(q^cx^2\right) \subset \mathcal{S}_{\mathbb{C}}\left(x^{2-2c}\right)$. Moreover, all elements of $\mathcal{T}_{\mathbb{C}} \big(sq^c x^d \big) \cap \mathcal{S}_{\mathbb{C}} \big(tx^{d-2c}\big)$ have common zeros at:
\[
\begin{cases}
z = m\tau + n, &\textnormal{if }\ t = -1, \\
z = m\tau + n + \frac{1}{2}, &\textnormal{if }\ t = (-1)^{d+1}, 
\\
z = \left(m + \frac{1}{2}\right)\tau + \frac{n}{2}, &\textnormal{if }\ st = -1,
\qquad\qquad\qquad \forall m,n \in \mathbb{Z}.
\end{cases}
\]

\end{itemize}

