\label{lem:basic-E}
Let $\tau \in {\mathbb{H}}^+$ and fix a level $N$.
\begin{itemize}
    \item[(i).] If $N$ is odd, $\prod_{g=1}^{\lfloor N/2 \rfloor} \textnormal E_g(\tau) = \frac{\eta(\tau)}{\eta(N\tau)}$.
    \item[(ii).] If $N$ is even, $\prod_{g=1}^{(N/2)-1} \textnormal E_g(\tau) = \frac{\eta(\tau)}{\eta(N\tau/2)}$.
    \item[(iii).] For any $g \in \mathbb{Z}$, $\textnormal E_g(\tau) = \textnormal E_{N-g}(\tau) = -\textnormal E_{g+N}(\tau)$. In particular, $\textnormal E_0(\tau) = 0$.
\end{itemize}

