    \begin{pmatrix}
    \vect{\alpha x^d}{\ell}
    \end{pmatrix}_{0 \le l < d}
    }_{\text{Canonical basis}},
\end{equation}

Assume without loss of generality that $|y| \le 1$, by the uniqueness of analytic continuation; then we have $1 - q^{-1} x^{-1} y \neq 0$ in $\{\textnormal{Im}\ z < -\textnormal{Im}\ \tau\}$, and thus the canonical basis vectors of $\mathcal{T}_{\mathbb{H}^{\textnormal{-}\hspace{-0.03cm}}} \left(\alpha x^d \left(1 - q^{-1} x^{-1} y\right) \right)$ are well-defined by \cref{prop:canonical-basis-vectors}. Now consider the following three elements of $\mathcal{T}_{\mathbb{C}}\left(\alpha x^d\right)^d$:
\begin{center}
\small
\begin{tikzcd} [column sep = -0.5cm]
    & 
    \begin{pmatrix} 
    \vect{\alpha x^d}{k}
    \end{pmatrix}_{0 \le k < d}
    \arrow{rd}{=\ U \ \cdot}
    \\
    \begin{pmatrix}
    \sum_{n \in \mathbb{Z}} \alpha^n q^{d\binom{n}{2}+kn} x^{dn+k} \left(q^{-n} x^{-1} y; q\right)
    \end{pmatrix}_{0 \le k < d}
    \arrow{rr}{=\ WU\ \cdot}
    \arrow{ru}{=\ W\ \cdot}
    &&
    \begin{pmatrix} 
    \left(x^{-1}y; q\right)\vect{\alpha x^d\left(1 - q^{-1}x^{-1}y\right)}{k}
    \end{pmatrix}_{0 \le k < d}
\end{tikzcd}
\end{center}
where the arrows indicate claimed relationships. The ``$= W \cdot\ $'' arrow is precisely the relation from \cref{eq:twist-change-canonical} for $a = 1$. The ``$= U \cdot\ $'' relation follows from \cref{eq:basic2} by expanding
\[
    \frac{1}{\left(x^{-1}y; q\right)} \vect{\alpha x^d}{k} 
    =
    \sum_{m \ge 0} \frac{\left(-x^{-1}y\right)^m}{(q; q)_m} \sum_{n \in \mathbb{Z}} \alpha^n q^{d\binom{n}{2}+kn} x^{dn+k},
\]
and identifying Fourier coefficients in the canonical basis of $\mathcal{T}_{\mathbb{H}^{\textnormal{-}\hspace{-0.03cm}}} \left(\alpha x^d \left(1 - q^{-1} x^{-1} y\right) \right)$. The ``$= WU\ \cdot$'' relation follows from the previous two, and will be helpful in computing $WU$.

Next, the fact that $W = \prod_{n \ge 0} M\left(q^n y\right)$ follows immediately by iterating \cref{lem:y-interpolation}, using that
\[
    \lim_{p \to \infty} \sum_{n \in \mathbb{Z}} \alpha^n q^{d\binom{n}{2}+kn} x^{dn+k} \left(q^{-n} x^{-1} (q^p y); q\right)
    =
    \vect{\alpha x^d}{k}.
\]
In particular, this shows that $\det W = 1$ (since each $\det M\left(q^n y\right) = 1$), and in particular that $\left(\vect{\alpha x^d}{k}\right)_{0 \le k < d}$ is invertible is indeed a basis of $\mathcal{T}_{\mathbb{C}}\left(\alpha x^d\right)$ as well. Hence we can compute $(WU)^{-1}$ as the unique change-of-basis matrix satisfying
\[
    \begin{pmatrix} 
    \left(x^{-1}y; q\right)\vect{\alpha x^d\left(1 - q^{-1}x^{-1}y\right)}{k}
    \end{pmatrix}_{0 \le k < d}
    =
    (WU)^{-1} 
    \begin{pmatrix}
    \sum_{n \in \mathbb{Z}} \alpha^n q^{d\binom{n}{2}+kn} x^{dn+k} \left(q^{-n} x^{-1} y; q\right)
    \end{pmatrix}_{0 \le k < d}.
\]
But by \cref{prop:exact-formulae-kind2} for $g(-z) = 1 - q^{-1}x^{-1}y$, we have
\[
    \left(x^{-1}y; q\right)\vect{\alpha x^d\left(1 - q^{-1}x^{-1}y\right)}{k}
    =
    \begin{cases}
    \sum_{n \in \mathbb{Z}} q^{d\binom{n}{2}} x^{dn} \left(q^{-n+1}x^{-1}y; q\right), 
    & k = 0,
    \\
    \sum_{n \in \mathbb{Z}} q^{d\binom{n}{2}+kn} x^{dn+k} \left(q^{-n}x^{-1}y; q\right),
    & k > 0.
    \end{cases}
\]
Using the relationship $V_0(x, qy) = V_0(x, y) + \alpha y q^{-1}$ from the proof of \cref{lem:y-interpolation}, this proves that
\[
    (WU)^{-1} = \begin{psmall} 
    1 & 0 & \cdots & 0 & \alpha y q^{-1}
    \\
    0 & 1 & \cdots & 0 & 0 
    \\
    & & & \ddots & \\
    0 & 0 & \cdots & 0 & 1
    \end{psmall}
    \qquad \Rightarrow 
    \qquad 
    WU = \begin{psmall} 
    1 & 0 & \cdots & 0 & -\alpha y q^{-1}
    \\
    0 & 1 & \cdots & 0 & 0 
    \\
    & & & \ddots & \\
    0 & 0 & \cdots & 0 & 1
    \end{psmall}.
\]
Finally, from $\det W = 1$ and $\det (WU) = 1$ we also deduce that $\det U = 1$.

\[
