    f_1(q) + 2\psi_1(q) = \sum_{n \in \mathbb{Z}} \frac{q^{n^2+n}}{(-q; q)_n} &= 
    q^{-\frac{11}{60}} \left(-\frac{\eta(\tau)^2}{\eta(2\tau)\textnormal E_2(\tau)} + 4\frac{\eta(4\tau)^2}{\eta(\tau) \textnormal E_1(4\tau)} \right),
    \\
    F_0(q) + \phi_0(-q) - 1 = 
    \sum_{n \in \mathbb{Z}} \frac{q^{2n^2}}{(q; q^2)_n} &= 
    q^{\frac{1}{120}}
    \Bigg( 
    \frac{\eta(4\tau)^6}
    {\eta(\tau) \eta(2\tau)^2 \eta(q^8)^2 \textnormal E_1(8\tau)}
    \\
    &\qquad
    +
    2\frac{\eta(2\tau)^4 \eta(8\tau)^4}
    {\eta(\tau) \eta(4\tau)^6 \textnormal E_2(2\tau)}
    -
    4\frac{\eta(2\tau)^2 \eta(8\tau)^6}
    {\eta(\tau) \eta(4\tau)^6 \textnormal E_1(8\tau)}
    \Bigg),
    \\
    F_1(q) + q^{-1} \phi_1(-q) = 
    \sum_{n \in \mathbb{Z}} \frac{q^{2n^2-2n}}{(q; q^2)_n}
    &=
    q^{-\frac{71}{120}}
    \Bigg(-\frac{\eta(4\tau)^6}
    {\eta(\tau) \eta(2\tau)^2 \eta(q^8)^2 \textnormal E_2(8\tau)}
    \\
    &\qquad
    +
    2\frac{\eta(2\tau)^4 \eta(8\tau)^4}
    {\eta(\tau) \eta(4\tau)^6 \textnormal E_1(2\tau)}
    +
    4\frac{\eta(2\tau)^2 \eta(8\tau)^6}
    {\eta(\tau) \eta(4\tau)^6 \textnormal E_2(8\tau)}
    \Bigg).
\end{aligned}
\]
(The advantage of writing the right-hand sides above in terms of $\eta$ and $\textnormal E_g$ is knowing which powers of $q$ are required to make the left-hand sides behave nicely under modular transformations.)

