\begin{equation} \label{eq:truncations}
\begin{aligned}
    &\vect{qx^2-q^{-1}}{0}_{\ge 0} = 
    \sum_{n \ge 0} \frac{q^{n^2}}{\left(-q; q^2\right)_n} x^{2n}
    ,
    \qquad\qquad 
    \vect{qx^2-q^{-1}}{1}_{\ge 0} = 
    \sum_{n \ge 0} \frac{q^{n^2+n}}{\left(-q^2; q^2\right)_n} x^{2n+1}
    ,
    \\
    &\qquad \vect{qx^2-x}{0}_{\ge 1} = 
    \sum_{n \ge 1} q^{n^2} x^{2n} \left(q^{-n+1} x^{-1}; q\right)_{n-1}
    \ =\
    \sum_{n \ge 1} q^{\binom{n+1}{2}} (-x)^{n+1} (qx; q)_{n-1},
    \\
    &\qquad \vect{qx^2-x}{1}_{\ge 1} =
    \sum_{n \ge 0} q^{n^2+n} x^{2n+1} \left(q^{-n} x^{-1}; q\right)_n
    \ =\
    -\sum_{n \ge 0} q^{\binom{n+1}{2}} (-x)^{n+1} (qx; q)_n,
\end{aligned}
\end{equation}

 \label{prop:mock-theta-individual}
Let $\tau \in {\mathbb{H}}^+$. Using \cref{not:mock-theta} and \cref{eq:explicit-matrix}, one has
\begin{gather*}
    \begin{pmatrix}
    \psi_0(q) \\
    \psi_1(q) 
    \end{pmatrix}
    =
    \begin{pmatrix}
    A(q) & B(q) \\
    C(q) & D(q)
    \end{pmatrix}
    \begin{pmatrix}
    \sum_{2n > m \ge 0} \frac{q^{n^2}(-1)^m}{(q; q)_m} \vspace{0.1cm}\\
    \sum_{2n \ge m \ge 0} \frac{q^{n^2+n}(-1)^m}{(q; q)_m}
    \end{pmatrix},
    \\
    \begin{pmatrix}
    \phi_1(q) \\
    \phi_0(q) 
    \end{pmatrix}
    =
    \begin{pmatrix}
    A\left(q^2\right) & B\left(q^2\right) \\
    C\left(q^2\right) & D\left(q^2\right)
    \end{pmatrix}
    \begin{pmatrix}
    q\sum_{2n > m \ge 0} \frac{q^{2n^2-2n} (-q)^m}{\left(q^2; q^2\right)_m} 
    \vspace{0.1cm}\\
    \sum_{2n \ge m \ge 0} \frac{q^{2n^2} (-q)^m}{\left(q^2; q^2\right)_m} 
    \end{pmatrix}.
\end{gather*}
Similar but simpler identities can be given for the third-order mock theta functions $\psi(q)$ and $\phi(q)$.

\begin{gather*}
    \begin{pmatrix}
