The mock theta conjectures (given different proofs in \cite{hickerson1988proof,folsom2008short}) relate the fifth-order mock theta functions to special values of the widely studied function \cite{ramanujan1988lost,dyson1944some,bringmann2010dyson,andrews2018four} 
\begin{equation}\label{eq:generalized-mock-theta}
    G(y, q) := \sum_{n \ge 0} \frac{q^{n^2}}{(qy; q)_n (q/y; q)_n},
\end{equation}
for $y \in \mathbb{C}$. The natural approach to this function in the context of this section is to consider the generalization
\[
    G(x, y, q) := \sum_{n \ge 0} \frac{q^{n^2}x^{2n}}{(qxy; q)_n (qx/y; q)_n}
    =
    \left(\frac{1}{(qxy; q)(qx/y; q)} \sum_{n \in \mathbb{Z}} q^{n^2}x^{2n} \left(q^{n+1}xy; q\right) \left(q^{n+1}x/y; q\right) \right)_{\ge 0},
\]
where $F_{\ge 0}$ indicates the truncation to nonnegative powers of $x$ as before. The sum over $n \in \mathbb{Z}$ above is a doubly-twisted version of the series $\sum_{n \in \mathbb{Z}} q^{n^2} x^{2n} \in \mathcal{T}_{\mathbb{C}}\left(qx^2\right)$, in the sense of \cref{eq:w-coeffs}; hence it also belongs to $\mathcal{T}_{\mathbb{C}}\left(qx^2\right)$, and can be expanded using a similar argument to \cref{lem:t-identities}. This leads to the following statement, which is ultimately a consequence of \cref{prop:fractional}.

\begin{equation}\label{eq:generalized-mock-theta}
    G(y, q) := \sum_{n \ge 0} \frac{q^{n^2}}{(qy; q)_n (q/y; q)_n},
\end{equation}

 \label{prop:double-twist}
Let $y \in \mathbb{C}^\times$. In $\mathcal{T}_{\mathbb{C}}\left(qx^2\right)$, one has
\[
\begin{aligned}
    (q; q)^2 \sum_{n \in \mathbb{Z}}
    q^{n^2} x^{2n} \left(q^{n+1} xy; q \right) \left(q^{n+1} x/y; q \right)
    &=
    \vect{qx^2}{0}\sum_{\substack{d \in \mathbb{Z} \\ d \textnormal{ even}}} \Big(q^{\frac{d^2 + 2|d|}{4}} \sum_{n \ge 0} (-1)^n q^{\binom{n+1}{2} + |d|n}\Big) y^d
    \\
    &- 
    \vect{qx^2}{1} \sum_{\substack{d \in \mathbb{Z} \\ d \textnormal{ odd}}} \Big(q^{\frac{(|d|+1)^2}{4}}  \sum_{n \ge 0} (-1)^n q^{\binom{n+1}{2} + |d|n}\Big) y^d.
\end{aligned}
\]

 \label{qtn:double-twist}
Can one use \cref{prop:double-twist} to:
\begin{itemize}
    \item[(i).] Obtain a \cref{prop:mock-theta-sums}-type formula for the sum $\sum_{n \in \mathbb{Z}} q^{n^2} (-q; q)_n^{-2}$ (by specialization at $xy = x/y = -1$), and a \cref{prop:mock-theta-individual}-type formula for the third-order mock theta function $f(q) := \sum_{n \ge 0} q^{n^2} (-q; q)_n^{-2}$ (see, e.g., \cite{chen2012partition})?
    \item[(ii).] Obtain relevant identities for the sum $G(y, q)$ from \cref{eq:generalized-mock-theta}, via its generalization $G(x, y, q)$?
\end{itemize}
